-- ============================================
-- DATABASE SCHEMA
-- ============================================
CREATE DATABASE IF NOT EXISTS online_shopping_db;
USE online_shopping_db;


-- Table: branches
DROP TABLE IF EXISTS branches;
CREATE TABLE branches (
    Branch_ID INT PRIMARY KEY,
    Branch_Name VARCHAR(50) NOT NULL,
    Location VARCHAR(50) NOT NULL,
    Phone_Number VARCHAR(20)
);

-- Table: categories
DROP TABLE IF EXISTS categories;
CREATE TABLE categories (
    Category_ID INT PRIMARY KEY,
    Category_Name VARCHAR(50) NOT NULL
);

-- Table: customers
DROP TABLE IF EXISTS customers;
CREATE TABLE customers (
    `ï»¿Customer_ID` INT PRIMARY KEY,
    Customer_Name VARCHAR(50) NOT NULL,
    Email VARCHAR(50),
    Phone VARCHAR(20),
    Gender VARCHAR(10),
    City VARCHAR(30),
    Registration_Date DATE
);

-- Table: employees
DROP TABLE IF EXISTS employees;
CREATE TABLE employees (
    Employee_ID INT PRIMARY KEY,
    Employee_Name VARCHAR(50) NOT NULL,
    Job_Title VARCHAR(30),
    Salary DECIMAL(10,2),
    Phone_Number VARCHAR(20),
    Email VARCHAR(50),
    Gender VARCHAR(10),
    BranchID INT,
    FOREIGN KEY (BranchID) REFERENCES branches(Branch_ID)
);

-- Table: deliveries
DROP TABLE IF EXISTS deliveries;
CREATE TABLE deliveries (
    `ï»¿Delivery_ID` INT PRIMARY KEY,
    Delivery_Date DATE,
    Delivery_Status VARCHAR(20)
);

-- Table: products
DROP TABLE IF EXISTS products;
CREATE TABLE products (
    `ï»¿Product_ID` INT PRIMARY KEY,
    Product_Name VARCHAR(100) NOT NULL,
    Description VARCHAR(50),
    Price DECIMAL(10,2),
    Stock_Quantity INT,
    CategoryID INT,
    FOREIGN KEY (CategoryID) REFERENCES categories(Category_ID)
);

-- Table: orders
DROP TABLE IF EXISTS orders;
CREATE TABLE orders (
    Order_ID INT PRIMARY KEY,
    Order_Date DATE,
    Order_Status VARCHAR(20),
    Payment_Method VARCHAR(20),
    CustomerId INT,
    BranchId INT,
    DeliveryId INT,
    Total_Amount DECIMAL(10,2),
    FOREIGN KEY (CustomerId) REFERENCES customers(`ï»¿Customer_ID`),
    FOREIGN KEY (BranchId) REFERENCES branches(Branch_ID),
    FOREIGN KEY (DeliveryId) REFERENCES deliveries(`ï»¿Delivery_ID`)
);

-- Table: items
DROP TABLE IF EXISTS items;
CREATE TABLE items (
    `ï»¿OrderID` INT,
    ProductID INT,
    Quantity INT,
    Selling_Price DECIMAL(10,2),
    Total_Amount DECIMAL(10,2),
    PRIMARY KEY (`ï»¿OrderID`, ProductID),
    FOREIGN KEY (`ï»¿OrderID`) REFERENCES orders(Order_ID),
    FOREIGN KEY (ProductID) REFERENCES products(`ï»¿Product_ID`)
);

-- Table: order_activity
DROP TABLE IF EXISTS order_activity;
CREATE TABLE order_activity (
    Activity_ID INT PRIMARY KEY,
    Activity_Type VARCHAR(30),
    Activity_Date DATE,
    Status VARCHAR(20),
    OrderId INT,
    EmployeeID INT,
    FOREIGN KEY (OrderId) REFERENCES orders(Order_ID),
    FOREIGN KEY (EmployeeID) REFERENCES employees(Employee_ID)
);

