-- ============================================
-- QUERIES
-- ============================================
USE online_shopping_db;
SELECT *
FROM customers;
SELECT
    Customer_Name,
    Email,
    Phone,
    City
FROM customers
WHERE City = 'Cairo';
SELECT DISTINCT
    City
FROM customers;
SELECT
    Customer_Name,
    Email
FROM customers
WHERE Customer_Name LIKE 'A%';
SELECT
    Order_Date,
    Total_Amount
FROM orders
WHERE Order_Date BETWEEN '2025-01-01' AND '2025-12-31';
SELECT COUNT(*) AS Total_Orders
FROM orders;
SELECT AVG(Total_Amount) AS Average_Order_Value
FROM orders;
SELECT MAX(Total_Amount) AS Highest_Order
FROM orders;
SELECT MIN(Total_Amount) AS Lowest_Order
FROM orders;
SELECT
    CustomerId,
    COUNT(*) AS Number_Of_Orders
FROM orders
GROUP BY CustomerId;
SELECT
    CustomerId,
    SUM(Total_Amount) AS Total_Spending
FROM orders
GROUP BY CustomerId;
SELECT
    CustomerId,
    AVG(Total_Amount) AS Average_Order_Value
FROM orders
GROUP BY CustomerId;
SELECT
    CustomerId,
    COUNT(*) AS Number_Of_Orders
FROM orders
GROUP BY CustomerId
HAVING COUNT(*) > 1;
SELECT
    Total_Amount,
    Order_Date
FROM orders
ORDER BY Total_Amount DESC;
SELECT
    Total_Amount,
    Order_Date
FROM orders
ORDER BY Total_Amount DESC
LIMIT 10;
SELECT
    Total_Amount,
    CASE
        WHEN Total_Amount >= 5000 THEN 'High'
        WHEN Total_Amount >= 2000 THEN 'Medium'
        ELSE 'Low'
    END AS Order_Category
FROM orders;
SELECT
    CASE
        WHEN Total_Amount >= 5000 THEN 'High'
        WHEN Total_Amount >= 2000 THEN 'Medium'
        ELSE 'Low'
    END AS Order_Category,
    COUNT(*) AS Number_Of_Orders
FROM orders
GROUP BY
    CASE
        WHEN Total_Amount >= 5000 THEN 'High'
        WHEN Total_Amount >= 2000 THEN 'Medium'
        ELSE 'Low'
    END;
    SELECT
    Order_Date,
    Total_Amount
FROM orders
WHERE Total_Amount > (
    SELECT AVG(Total_Amount)
    FROM orders
);
SELECT
    Order_Date,
    Total_Amount
FROM orders
WHERE Total_Amount = (
    SELECT MAX(Total_Amount)
    FROM orders
);
SELECT
    o.CustomerId,
    c.Customer_Name,
    o.Order_Date,
    o.Total_Amount
FROM orders AS o
JOIN customers AS c
    ON o.CustomerId = c.`ï»¿Customer_ID`;
    SELECT
    c.Customer_Name,
    SUM(o.Total_Amount) AS Total_Spending
FROM customers AS c
JOIN orders AS o
    ON o.CustomerId = c.`ï»¿Customer_ID`
GROUP BY
    c.Customer_Name;
    SELECT
    c.Customer_Name,
    SUM(o.Total_Amount) AS Total_Spending
FROM customers AS c
JOIN orders AS o
    ON o.CustomerId = c.`ï»¿Customer_ID`
GROUP BY
    c.Customer_Name
HAVING SUM(o.Total_Amount) > 10000;
SELECT
    c.Customer_Name,
    AVG(o.Total_Amount) AS Average_Order_Value
FROM customers AS c
JOIN orders AS o
    ON o.CustomerId = c.`ï»¿Customer_ID`
GROUP BY
    c.Customer_Name;
    SELECT
    CONCAT(Customer_Name, ' - ', City) AS Customer_Info
FROM customers;
SELECT
    UPPER(Customer_Name) AS Customer_Name
FROM customers;
SELECT
    LOWER(Customer_Name) AS Customer_Name
FROM customers;
SELECT
    o.CustomerId,
    c.Customer_Name,
    o.Order_Date,
    o.Total_Amount
FROM orders AS o
INNER JOIN customers AS c
    ON o.CustomerId = c.`ï»¿Customer_ID`;
    SELECT
    c.Customer_Name,
    o.Order_Date,
    o.Total_Amount
FROM customers AS c
LEFT JOIN orders AS o
    ON o.CustomerId = c.`ï»¿Customer_ID`;
    SELECT
    c.Customer_Name,
    o.Order_Date,
    o.Total_Amount
FROM customers AS c
RIGHT JOIN orders AS o
    ON o.CustomerId = c.`ï»¿Customer_ID`;
    SELECT
    Customer_Name,
    COALESCE(Email, 'No Email') AS Customer_Email
FROM customers;
SELECT
    Customer_Name,
    IF(Email IS NULL, 'No Email', 'Has Email') AS Email_Status
FROM customers;
USE online_shopping_db;

SELECT
    o.CustomerId,
    o.BranchId,
    b.Branch_Name,
    b.Location
FROM orders AS o
JOIN branches AS b
    ON o.BranchId = b.Branch_ID;
    USE online_shopping_db;

SELECT
    o.CustomerId,
    o.DeliveryId,
    d.Delivery_Date,
    d.Delivery_Status
FROM orders AS o
JOIN deliveries AS d
    ON o.DeliveryId = d.`ï»¿Delivery_ID`;
    USE online_shopping_db;

SELECT
    o.CustomerId,
    c.Customer_Name,
    b.Branch_Name,
    b.Location
FROM orders AS o
JOIN customers AS c
    ON o.CustomerId = c.`ï»¿Customer_ID`
JOIN branches AS b
    ON o.BranchId = b.Branch_ID;
    USE online_shopping_db;

SELECT
    c.Customer_Name,
    b.Branch_Name,
    d.Delivery_Date,
    d.Delivery_Status,
    o.Total_Amount
FROM orders AS o
JOIN customers AS c
    ON o.CustomerId = c.`ï»¿Customer_ID`
JOIN branches AS b
    ON o.BranchId = b.Branch_ID
JOIN deliveries AS d
    ON o.DeliveryId = d.`ï»¿Delivery_ID`;
    USE online_shopping_db;

USE online_shopping_db;

SELECT
    i.`ï»¿OrderID`,
    i.ProductID,
    p.Product_Name,
    i.Quantity,
    i.Selling_Price,
    i.Total_Amount
FROM items AS i
JOIN products AS p
    ON i.ProductID = p.`ï»¿Product_ID`;
    USE online_shopping_db;

SELECT
    b.Branch_Name,
    COUNT(o.CustomerId) AS Total_Orders
FROM branches AS b
JOIN orders AS o
    ON b.Branch_ID = o.BranchId
GROUP BY b.Branch_ID, b.Branch_Name;
USE online_shopping_db;

